// Small helpers shared by the core logic. Inlined into each Code node by scripts/build-workflows.js.

const clean = (v) => String(v ?? '').trim();
const lower = (v) => clean(v).toLowerCase();
const truthy = (v) => ['true', 'yes', '1', 'y'].includes(lower(v));
// Slack markdown: escape its three control characters so names, titles, lookup text or AI output
// can't add links, @channel pings or mentions to an alert.
const mdEsc = (v) => clean(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Only plain http(s) links, with nothing that could break out of a Slack or HTML link (no javascript: or data:).
const safeUrl = (v) => { const u = clean(v); return /^https?:\/\/[^\s<>|"'`]+$/i.test(u) ? u : ''; };

function parseJson(value, fallback) {
  if (value && typeof value === 'object') return value;
  const s = clean(value);
  if (!s) return fallback;
  try { return JSON.parse(s); } catch (e) { return fallback; }
}

function normDomain(s) {
  let d = lower(s);
  if (!d) return '';
  d = d.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0];
  if (d.includes('@')) d = d.split('@').pop();
  return d;
}

function splitName(full) {
  const parts = clean(full).split(/\s+/).filter(Boolean);
  if (!parts.length) return { first_name: '', last_name: '' };
  if (parts.length === 1) return { first_name: parts[0], last_name: '' };
  return { first_name: parts[0], last_name: parts.slice(1).join(' ') };
}

// Stable 1, 2 or 3 from a contact_id, so a third of the list is swept each month without anyone assigning groups.
function sweepGroupFor(id) {
  let h = 0;
  const s = clean(id);
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return String((h % 3) + 1);
}

const isoDay = (d) => d.toISOString().slice(0, 10);

// Team directory (Config): { "<email, CRM owner id or name>": { name, email, slack_id, crm_id, salesloft_user_id }, "default": {...} }
function loadDirectory(cfg) {
  const raw = parseJson(cfg.team_directory, {}) || {};
  const dir = {};
  for (const [k, v] of Object.entries(raw)) dir[lower(k)] = v && typeof v === 'object' ? v : {};
  return dir;
}

// Fills an owner's missing name / email / Slack ID / CRM ID / sequence user ID from the directory.
function resolveOwner(dir, owner, useDefault = true) {
  const o = owner || {};
  let entry = dir[lower(o.email)] || dir[lower(o.crm_id)] || dir[lower(o.name)];
  const hasOwner = clean(o.name) || clean(o.email) || clean(o.crm_id);
  if (!entry && !hasOwner && useDefault) entry = dir.default;
  entry = entry || {};
  return {
    name: clean(o.name) || clean(entry.name),
    email: lower(o.email) || lower(entry.email),
    slack_id: clean(o.slack_id) || clean(entry.slack_id),
    crm_id: clean(o.crm_id) || clean(entry.crm_id),
    sequence_user_id: clean(o.sequence_user_id) || clean(entry.salesloft_user_id || entry.sequence_user_id),
  };
}

// Merges the CRM watchlist, an optional product-user list and saved tracker state into one list of champions.
// Pure function: tested in test/, inlined into the "Build Watchlist" Code node.


function buildWatchlist(cfg, crmRows, productRows, stateRows) {
  const dir = loadDirectory(cfg);

  const state = new Map();
  for (const s of stateRows || []) if (clean(s.contact_id)) state.set(clean(s.contact_id), s);

  const normalize = (r, source) => {
    const email = lower(r.work_email);
    const id = clean(r.contact_id) || (email ? `${source}:${email}` : '');
    if (!id) return null;
    const names = splitName(r.full_name);
    const owner = resolveOwner(dir, { name: r.owner_ae, email: r.owner_ae_email, slack_id: r.owner_ae_slack_id, crm_id: r.owner_crm_id, sequence_user_id: r.owner_sequence_user_id });
    const full = clean(r.full_name) || [clean(r.first_name), clean(r.last_name)].filter(Boolean).join(' ');
    return {
      contact_id: id,
      full_name: full,
      first_name: clean(r.first_name) || names.first_name,
      last_name: clean(r.last_name) || names.last_name,
      work_email: email,
      linkedin_url: clean(r.linkedin_url),
      last_company: clean(r.last_company),
      last_company_domain: normDomain(r.last_company_domain) || (email.includes('@') ? normDomain(email) : ''),
      last_title: clean(r.last_title),
      role_type: ['buyer', 'champion', 'user'].includes(lower(r.role_type)) ? lower(r.role_type) : 'user',
      owner_ae: owner.name,
      owner_ae_email: owner.email,
      owner_ae_slack_id: owner.slack_id,
      owner_crm_id: owner.crm_id,
      owner_sequence_user_id: owner.sequence_user_id,
      do_not_contact: truthy(r.do_not_contact) ? 'TRUE' : 'FALSE',
      notes: clean(r.notes),
      sweep_group: ['1', '2', '3'].includes(clean(r.sweep_group)) ? clean(r.sweep_group) : sweepGroupFor(id),
      source,
    };
  };

  const byId = new Map();
  const byEmail = new Map();
  for (const r of crmRows || []) {
    if (!r || typeof r !== 'object') continue;
    const c = normalize(r, 'crm');
    if (!c || byId.has(c.contact_id)) continue;
    byId.set(c.contact_id, c);
    if (c.work_email) byEmail.set(c.work_email, c);
  }
  // Product users fill gaps on matching CRM contacts, or are added as new champions.
  for (const r of productRows || []) {
    if (!r || typeof r !== 'object') continue;
    const p = normalize(r, 'product');
    if (!p) continue;
    const existing = p.work_email && byEmail.get(p.work_email);
    if (existing) {
      for (const [k, v] of Object.entries(p)) if (!existing[k] && v) existing[k] = v;
      if (existing.source === 'crm') existing.source = 'crm+product';
      continue;
    }
    if (byId.has(p.contact_id)) continue;
    byId.set(p.contact_id, p);
    if (p.work_email) byEmail.set(p.work_email, p);
  }

  return [...byId.values()].map((c) => {
    const s = state.get(c.contact_id) || {};
    return {
      ...c,
      status: lower(s.status) || 'active',
      last_checked: clean(s.last_checked),
      next_check_on: clean(s.next_check_on),
    };
  });
}

// Decides who to investigate on this run: inbox signals, due [verify] rechecks, failed runs, and the monthly sweep.
// Pure function: tested in test/, inlined into the "Find Candidates" Code node.


function findCandidates(cfg, champions, messages, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const max = Number(cfg.max_lookups_per_run) || 40;
  const sweepDay = Number(cfg.sweep_day_of_month) || 1;
  const toDate = (v) => {
    const d = new Date(clean(v));
    return clean(v) && !isNaN(d.getTime()) ? d : null;
  };
  const daysSince = (d) => (now.getTime() - d.getTime()) / 86400000;
  const pack = (c, trigger, signal, evidence = '', signalDate = '') => ({ ...c, trigger, signal, signal_evidence: evidence, signal_date: signalDate });

  // 1. A teammate asked for one person (from the MCP server or another workflow).
  const requested = clean(cfg.requested_contact_id);
  if (requested) {
    const c = champions.find((p) => p.contact_id === requested || lower(p.work_email) === lower(requested));
    if (!c) return { candidates: [], skipped: [`Unknown contact ${requested}`] };
    if (truthy(c.do_not_contact)) return { candidates: [], skipped: [`${requested} is marked do_not_contact`] };
    return { candidates: [pack(c, 'manual', 'manual', 'Requested by a teammate')], skipped: [] };
  }

  const eligible = champions.filter((c) => !truthy(c.do_not_contact) && !['moved', 'inactive'].includes(c.status));
  const byEmail = new Map();
  for (const c of eligible) if (c.work_email) byEmail.set(lower(c.work_email), c);

  const chosen = new Map();
  const add = (cand) => { if (!chosen.has(cand.contact_id)) chosen.set(cand.contact_id, cand); };

  // 2. Inbox signals: bounces and "no longer with the company" auto-replies.
  const emailRe = /[a-z0-9._%+'-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;
  const bounceRe = /mailer-daemon|postmaster|undeliver|delivery status notification|delivery has failed|delivery failure|mail delivery failed|returned mail|not be delivered|address not found|recipient address rejected/i;
  const leftRe = /no longer (with|at|employed|working|part of)|has left (the company|the organization|the organisation|[a-z0-9 &.,'-]{2,40})|left the company|last day (was|at)|is no longer/i;
  for (const m of messages || []) {
    if (!m || typeof m !== 'object') continue;
    const subject = clean(m.subject || m.Subject);
    const fromBlob = typeof (m.from ?? m.From) === 'string' ? (m.from ?? m.From) : JSON.stringify(m.from ?? m.From ?? '');
    const blob = [subject, fromBlob, JSON.stringify(m.headers ?? {}), clean(m.text) || clean(m.snippet)].join('\n');
    const found = new Set((blob.match(emailRe) || []).map((e) => e.toLowerCase()));
    if (!found.size) continue;
    // A bounce must come from a mail system (mailer-daemon or postmaster), so anyone can't email
    // "Undeliverable: ..." and make Valari spend lookup credits on a person who didn't leave.
    const fromMailSystem = /mailer-daemon|postmaster/i.test(fromBlob);
    const isBounce = fromMailSystem && (bounceRe.test(subject) || bounceRe.test(fromBlob));
    const isLeft = !isBounce && leftRe.test(blob);
    if (!isBounce && !isLeft) continue;
    const fromEmails = new Set((fromBlob.match(emailRe) || []).map((e) => e.toLowerCase()));
    const day = clean(m.date).slice(0, 10);
    for (const email of found) {
      const c = byEmail.get(email);
      if (!c) continue;
      if (isLeft && !fromEmails.has(email)) continue; // only the champion's own auto-reply counts
      const evidence = `${isBounce ? 'Email bounced' : 'Auto-reply says they left'}${day ? ` on ${day}` : ''}: "${subject.slice(0, 120)}"`;
      add(pack(c, 'signal', isBounce ? 'bounce' : 'left_autoreply', evidence, day));
    }
  }

  // 3. [verify] cases due for a recheck.
  for (const c of eligible) {
    if (c.status !== 'verify') continue;
    const due = toDate(c.next_check_on);
    if (!due || daysSince(due) >= 0) add(pack(c, 'recheck', 'recheck', `Scheduled recheck (due ${c.next_check_on || 'now'})`));
  }

  // 4. Suspects left behind by a run that failed midway.
  for (const c of eligible) {
    if (c.status !== 'suspect') continue;
    const last = toDate(c.last_checked);
    if (!last || daysSince(last) >= 2) add(pack(c, 'retry', 'retry', 'Previous investigation did not finish'));
  }

  // 5. Monthly sweep: one third of the list each month, so everyone is checked once a quarter.
  if (now.getUTCDate() === sweepDay) {
    const group = String((now.getUTCMonth() % 3) + 1);
    for (const c of eligible) {
      if (c.status === 'active' && c.sweep_group === group) add(pack(c, 'sweep', 'sweep', `Quarterly sweep, group ${group}`));
    }
  }

  const all = [...chosen.values()];
  return {
    candidates: all.slice(0, max),
    skipped: all.slice(max).map((c) => `${c.contact_id} (over the ${max} lookups-per-run cap, picked up next run)`),
  };
}

// A manual run for someone whose lookup was still in progress (the Lookup Callback re-runs people this way)
// keeps the bounce or auto-reply that started it, so "nothing found" still ends as [VERIFY], not "no change".
// Only signals from the last lookup_repeat_days (default 30) count.
function restoreSignals(cfg, candidates, cacheRows, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const maxDays = Number(cfg.lookup_repeat_days ?? 30);
  return (candidates || []).map((c) => {
    if (c.trigger !== 'manual') return c;
    const row = (cacheRows || []).find((r) => r && clean(r.contact_id) === c.contact_id);
    const saved = row ? parseJson(row.signal_json, null) : null;
    if (!saved || !['signal', 'retry', 'recheck'].includes(saved.trigger)) return c;
    const at = new Date(clean(saved.signal_date) || clean(saved.saved_at));
    if (isNaN(at.getTime()) || (now - at) / 86400000 > maxDays) return c;
    return { ...c, trigger: saved.trigger, signal: saved.signal, signal_evidence: saved.signal_evidence, signal_date: saved.signal_date, requested: true };
  });
}

// People whose async lookup (Clay) answered since the last run. They are added on top of the per-run cap,
// since their lookup is already paid for, and keep the signal that started the lookup.
function readyCandidates(candidates, watchlist, cacheRows) {
  const have = new Set((candidates || []).map((c) => c.contact_id));
  const out = [...(candidates || [])];
  for (const r of cacheRows || []) {
    if (!r || lower(r.pending) !== 'ready' || have.has(clean(r.contact_id))) continue;
    const c = (watchlist || []).find((p) => p.contact_id === clean(r.contact_id));
    if (!c || truthy(c.do_not_contact) || ['moved', 'inactive'].includes(c.status)) continue;
    const saved = parseJson(r.signal_json, null) || {};
    out.push({ ...c, trigger: saved.trigger || 'retry', signal: saved.signal || 'lookup_answer', signal_evidence: clean(saved.signal_evidence), signal_date: clean(saved.signal_date) });
    have.add(c.contact_id);
  }
  return out;
}

// People marked do_not_contact who are still tracked: their state becomes "opted_out", so "call now" alerts
// (which only fire for "moved") stop too. Removing the flag later makes them eligible again.
function optOutRows(watchlist) {
  return (watchlist || [])
    .filter((c) => truthy(c.do_not_contact) && c.status && !['active', 'opted_out'].includes(c.status))
    .map((c) => ({ contact_id: c.contact_id, full_name: c.full_name, status: 'opted_out' }));
}

// Small mapping helpers for the Gmail, Hunter and Salesloft connectors. Inlined into their Code nodes.

// Gmail (raw format) → the standard signal message.
function normalizeGmail(m) {
  const clean = (v) => String(v ?? '').trim();
  if (!m || typeof m !== 'object' || !m.id) return null;
  return {
    id: clean(m.id),
    subject: clean(m.subject || m.Subject),
    from: clean((m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || m.From),
    text: clean(m.text || m.snippet).slice(0, 4000),
    date: clean(m.date),
    headers: m.headers && typeof m.headers === 'object' ? m.headers : {},
  };
}

// Hunter Email Finder response → the standard email result.
function mapHunter(req, res) {
  const clean = (v) => String(v ?? '').trim();
  const d = (res && res.data) || {};
  const email = clean(d.email);
  const v = clean(d.verification && d.verification.status).toLowerCase();
  const status = !email ? '' : v === 'valid' ? 'valid' : v === 'invalid' ? 'invalid' : v === 'accept_all' ? 'risky' : 'unknown';
  return {
    contact_id: clean(req.contact_id),
    email,
    confidence: email && d.score !== undefined && d.score !== null ? Number(d.score) : '',
    status,
    source: 'hunter',
    error: res && res.error ? clean(res.error.message || res.error) : '',
  };
}

// Salesloft: pick the cadence for each enroll request, or say why it's skipped.
// cadenceIds: { "net_new": 123, "lost_deal": 456, "open_deal": 789, "customer": 101, "default": 999 }
function planSalesloft(requests, cadenceIds, userIdsByEmail) {
  const clean = (v) => String(v ?? '').trim();
  const cads = cadenceIds && typeof cadenceIds === 'object' ? cadenceIds : {};
  const users = {};
  for (const [k, v] of Object.entries(userIdsByEmail || {})) users[k.toLowerCase()] = v;
  return (requests || [])
    .filter((r) => r && r.action === 'enroll')
    .map((r) => {
      const cadence = cads[r.cadence_key] ?? cads.default;
      const cadenceId = cadence && typeof cadence === 'object' ? clean(cadence.id) : clean(cadence);
      const cadenceName = cadence && typeof cadence === 'object' ? clean(cadence.name) : '';
      return {
        ...r,
        cadence_id: cadenceId,
        cadence_name: cadenceName || cadenceId,
        user_id: clean(r.owner_sequence_user_id) || clean(users[clean(r.owner_email).toLowerCase()]),
        skip_reason: !cadenceId ? `no cadence set for "${r.cadence_key}"` : !clean(r.email) ? 'no email' : '',
      };
    });
}

// ---- n8n entry ----
const cfg = $('Config').first().json;
const rows = (name) => $(name).all().map((i) => i.json).filter((j) => j && Object.keys(j).length);
const watchlist = buildWatchlist(cfg, rows('Map Champions'), [], rows('Read State'));
const messages = rows('Search Inbox').map(normalizeGmail).filter(Boolean);
const { candidates, skipped } = findCandidates(cfg, watchlist, messages);
console.log(`Watchlist: ${watchlist.length} people. Investigating ${candidates.length}.`);
if (skipped.length) console.log('Skipped this run:', skipped);
return candidates.map((c) => ({ json: c }));

