// Merges the CRM watchlist, an optional product-user list and saved tracker state into one list of champions.
// Pure function: tested in test/, inlined into the "Build Watchlist" Code node.


function buildWatchlist(cfg, crmRows, productRows, stateRows) {
  const dir = loadDirectory(cfg);

  const state = new Map();
  for (const s of stateRows || []) if (clean(s.contact_id)) state.set(clean(s.contact_id), s);

  const normalize = (r, source) => {
    const email = lower(r.work_email);
    const id = clean(r.contact_id) || (email ? `${source}:${email}` : '');
    if (!id) return null;
    const names = splitName(r.full_name);
    const owner = resolveOwner(dir, { name: r.owner_ae, email: r.owner_ae_email, slack_id: r.owner_ae_slack_id, crm_id: r.owner_crm_id, sequence_user_id: r.owner_sequence_user_id });
    const full = clean(r.full_name) || [clean(r.first_name), clean(r.last_name)].filter(Boolean).join(' ');
    return {
      contact_id: id,
      full_name: full,
      first_name: clean(r.first_name) || names.first_name,
      last_name: clean(r.last_name) || names.last_name,
      work_email: email,
      linkedin_url: clean(r.linkedin_url),
      last_company: clean(r.last_company),
      last_company_domain: normDomain(r.last_company_domain) || (email.includes('@') ? normDomain(email) : ''),
      last_title: clean(r.last_title),
      role_type: ['buyer', 'champion', 'user'].includes(lower(r.role_type)) ? lower(r.role_type) : 'user',
      owner_ae: owner.name,
      owner_ae_email: owner.email,
      owner_ae_slack_id: owner.slack_id,
      owner_crm_id: owner.crm_id,
      owner_sequence_user_id: owner.sequence_user_id,
      do_not_contact: truthy(r.do_not_contact) ? 'TRUE' : 'FALSE',
      notes: clean(r.notes),
      sweep_group: ['1', '2', '3'].includes(clean(r.sweep_group)) ? clean(r.sweep_group) : sweepGroupFor(id),
      source,
    };
  };

  const byId = new Map();
  const byEmail = new Map();
  for (const r of crmRows || []) {
    if (!r || typeof r !== 'object') continue;
    const c = normalize(r, 'crm');
    if (!c || byId.has(c.contact_id)) continue;
    byId.set(c.contact_id, c);
    if (c.work_email) byEmail.set(c.work_email, c);
  }
  // Product users fill gaps on matching CRM contacts, or are added as new champions.
  for (const r of productRows || []) {
    if (!r || typeof r !== 'object') continue;
    const p = normalize(r, 'product');
    if (!p) continue;
    const existing = p.work_email && byEmail.get(p.work_email);
    if (existing) {
      for (const [k, v] of Object.entries(p)) if (!existing[k] && v) existing[k] = v;
      if (existing.source === 'crm') existing.source = 'crm+product';
      continue;
    }
    if (byId.has(p.contact_id)) continue;
    byId.set(p.contact_id, p);
    if (p.work_email) byEmail.set(p.work_email, p);
  }

  return [...byId.values()].map((c) => {
    const s = state.get(c.contact_id) || {};
    return {
      ...c,
      status: lower(s.status) || 'active',
      last_checked: clean(s.last_checked),
      next_check_on: clean(s.next_check_on),
    };
  });
}

// Decides who to investigate on this run: inbox signals, due [verify] rechecks, failed runs, and the monthly sweep.
// Pure function: tested in test/, inlined into the "Find Candidates" Code node.


function findCandidates(cfg, champions, messages, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const max = Number(cfg.max_lookups_per_run) || 40;
  const sweepDay = Number(cfg.sweep_day_of_month) || 1;
  const toDate = (v) => {
    const d = new Date(clean(v));
    return clean(v) && !isNaN(d.getTime()) ? d : null;
  };
  const daysSince = (d) => (now.getTime() - d.getTime()) / 86400000;
  const pack = (c, trigger, signal, evidence = '', signalDate = '') => ({ ...c, trigger, signal, signal_evidence: evidence, signal_date: signalDate });

  // 1. A teammate asked for one person (from the MCP server or another workflow).
  const requested = clean(cfg.requested_contact_id);
  if (requested) {
    const c = champions.find((p) => p.contact_id === requested || lower(p.work_email) === lower(requested));
    if (!c) return { candidates: [], skipped: [`Unknown contact ${requested}`] };
    if (truthy(c.do_not_contact)) return { candidates: [], skipped: [`${requested} is marked do_not_contact`] };
    return { candidates: [pack(c, 'manual', 'manual', 'Requested by a teammate')], skipped: [] };
  }

  const eligible = champions.filter((c) => !truthy(c.do_not_contact) && !['moved', 'inactive'].includes(c.status));
  const byEmail = new Map();
  for (const c of eligible) if (c.work_email) byEmail.set(lower(c.work_email), c);

  const chosen = new Map();
  const add = (cand) => { if (!chosen.has(cand.contact_id)) chosen.set(cand.contact_id, cand); };

  // 2. Inbox signals: bounces and "no longer with the company" auto-replies.
  const emailRe = /[a-z0-9._%+'-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;
  const bounceRe = /mailer-daemon|postmaster|undeliver|delivery status notification|delivery has failed|delivery failure|mail delivery failed|returned mail|not be delivered|address not found|recipient address rejected/i;
  const leftRe = /no longer (with|at|employed|working|part of)|has left (the company|the organization|the organisation|[a-z0-9 &.,'-]{2,40})|left the company|last day (was|at)|is no longer/i;
  for (const m of messages || []) {
    if (!m || typeof m !== 'object') continue;
    const subject = clean(m.subject || m.Subject);
    const fromBlob = typeof (m.from ?? m.From) === 'string' ? (m.from ?? m.From) : JSON.stringify(m.from ?? m.From ?? '');
    const blob = [subject, fromBlob, JSON.stringify(m.headers ?? {}), clean(m.text) || clean(m.snippet)].join('\n');
    const found = new Set((blob.match(emailRe) || []).map((e) => e.toLowerCase()));
    if (!found.size) continue;
    // A bounce must come from a mail system (mailer-daemon or postmaster), so anyone can't email
    // "Undeliverable: ..." and make Valari spend lookup credits on a person who didn't leave.
    const fromMailSystem = /mailer-daemon|postmaster/i.test(fromBlob);
    const isBounce = fromMailSystem && (bounceRe.test(subject) || bounceRe.test(fromBlob));
    const isLeft = !isBounce && leftRe.test(blob);
    if (!isBounce && !isLeft) continue;
    const fromEmails = new Set((fromBlob.match(emailRe) || []).map((e) => e.toLowerCase()));
    const day = clean(m.date).slice(0, 10);
    for (const email of found) {
      const c = byEmail.get(email);
      if (!c) continue;
      if (isLeft && !fromEmails.has(email)) continue; // only the champion's own auto-reply counts
      const evidence = `${isBounce ? 'Email bounced' : 'Auto-reply says they left'}${day ? ` on ${day}` : ''}: "${subject.slice(0, 120)}"`;
      add(pack(c, 'signal', isBounce ? 'bounce' : 'left_autoreply', evidence, day));
    }
  }

  // 3. [verify] cases due for a recheck.
  for (const c of eligible) {
    if (c.status !== 'verify') continue;
    const due = toDate(c.next_check_on);
    if (!due || daysSince(due) >= 0) add(pack(c, 'recheck', 'recheck', `Scheduled recheck (due ${c.next_check_on || 'now'})`));
  }

  // 4. Suspects left behind by a run that failed midway.
  for (const c of eligible) {
    if (c.status !== 'suspect') continue;
    const last = toDate(c.last_checked);
    if (!last || daysSince(last) >= 2) add(pack(c, 'retry', 'retry', 'Previous investigation did not finish'));
  }

  // 5. Monthly sweep: one third of the list each month, so everyone is checked once a quarter.
  if (now.getUTCDate() === sweepDay) {
    const group = String((now.getUTCMonth() % 3) + 1);
    for (const c of eligible) {
      if (c.status === 'active' && c.sweep_group === group) add(pack(c, 'sweep', 'sweep', `Quarterly sweep, group ${group}`));
    }
  }

  const all = [...chosen.values()];
  return {
    candidates: all.slice(0, max),
    skipped: all.slice(max).map((c) => `${c.contact_id} (over the ${max} lookups-per-run cap, picked up next run)`),
  };
}

// A manual run for someone whose lookup was still in progress (the Lookup Callback re-runs people this way)
// keeps the bounce or auto-reply that started it, so "nothing found" still ends as [VERIFY], not "no change".
// Only signals from the last lookup_repeat_days (default 30) count.
function restoreSignals(cfg, candidates, cacheRows, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const maxDays = Number(cfg.lookup_repeat_days ?? 30);
  return (candidates || []).map((c) => {
    if (c.trigger !== 'manual') return c;
    const row = (cacheRows || []).find((r) => r && clean(r.contact_id) === c.contact_id);
    const saved = row ? parseJson(row.signal_json, null) : null;
    if (!saved || !['signal', 'retry', 'recheck'].includes(saved.trigger)) return c;
    const at = new Date(clean(saved.signal_date) || clean(saved.saved_at));
    if (isNaN(at.getTime()) || (now - at) / 86400000 > maxDays) return c;
    return { ...c, trigger: saved.trigger, signal: saved.signal, signal_evidence: saved.signal_evidence, signal_date: saved.signal_date, requested: true };
  });
}

// People whose async lookup (Clay) answered since the last run. They are added on top of the per-run cap,
// since their lookup is already paid for, and keep the signal that started the lookup.
function readyCandidates(candidates, watchlist, cacheRows) {
  const have = new Set((candidates || []).map((c) => c.contact_id));
  const out = [...(candidates || [])];
  for (const r of cacheRows || []) {
    if (!r || lower(r.pending) !== 'ready' || have.has(clean(r.contact_id))) continue;
    const c = (watchlist || []).find((p) => p.contact_id === clean(r.contact_id));
    if (!c || truthy(c.do_not_contact) || ['moved', 'inactive'].includes(c.status)) continue;
    const saved = parseJson(r.signal_json, null) || {};
    out.push({ ...c, trigger: saved.trigger || 'retry', signal: saved.signal || 'lookup_answer', signal_evidence: clean(saved.signal_evidence), signal_date: clean(saved.signal_date) });
    have.add(c.contact_id);
  }
  return out;
}

// People marked do_not_contact who are still tracked: their state becomes "opted_out", so "call now" alerts
// (which only fire for "moved") stop too. Removing the flag later makes them eligible again.
function optOutRows(watchlist) {
  return (watchlist || [])
    .filter((c) => truthy(c.do_not_contact) && c.status && !['active', 'opted_out'].includes(c.status))
    .map((c) => ({ contact_id: c.contact_id, full_name: c.full_name, status: 'opted_out' }));
}

// ---- n8n entry ----
// Opted-out people who already moved (or are being checked): stop their alerts, including "call now".
const cfg = $('Config').first().json;
const rows = (name) => ($(name).isExecuted ? $(name).all().map((i) => i.json).filter((j) => j && Object.keys(j).length) : []);
const watchlist = buildWatchlist(cfg, rows('Map Champions'), [], rows('Read State'));
return optOutRows(watchlist).map((json) => ({ json }));

// People with an inbox signal are marked "suspect" first, so a failed run is retried instead of lost.
const today = new Date().toISOString().slice(0, 10);
return $input.all()
  .filter((i) => i.json.trigger === 'signal')
  .map((i) => ({ json: { contact_id: i.json.contact_id, full_name: i.json.full_name, status: 'suspect', last_checked: today } }));

// Small helpers shared by the core logic. Inlined into each Code node by scripts/build-workflows.js.

const clean = (v) => String(v ?? '').trim();
const lower = (v) => clean(v).toLowerCase();
const truthy = (v) => ['true', 'yes', '1', 'y'].includes(lower(v));
// Slack markdown: escape its three control characters so names, titles, lookup text or AI output
// can't add links, @channel pings or mentions to an alert.
const mdEsc = (v) => clean(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Only plain http(s) links, with nothing that could break out of a Slack or HTML link (no javascript: or data:).
const safeUrl = (v) => { const u = clean(v); return /^https?:\/\/[^\s<>|"'`]+$/i.test(u) ? u : ''; };

function parseJson(value, fallback) {
  if (value && typeof value === 'object') return value;
  const s = clean(value);
  if (!s) return fallback;
  try { return JSON.parse(s); } catch (e) { return fallback; }
}

function normDomain(s) {
  let d = lower(s);
  if (!d) return '';
  d = d.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0];
  if (d.includes('@')) d = d.split('@').pop();
  return d;
}

function splitName(full) {
  const parts = clean(full).split(/\s+/).filter(Boolean);
  if (!parts.length) return { first_name: '', last_name: '' };
  if (parts.length === 1) return { first_name: parts[0], last_name: '' };
  return { first_name: parts[0], last_name: parts.slice(1).join(' ') };
}

// Stable 1, 2 or 3 from a contact_id, so a third of the list is swept each month without anyone assigning groups.
function sweepGroupFor(id) {
  let h = 0;
  const s = clean(id);
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return String((h % 3) + 1);
}

const isoDay = (d) => d.toISOString().slice(0, 10);

// Team directory (Config): { "<email, CRM owner id or name>": { name, email, slack_id, crm_id, salesloft_user_id }, "default": {...} }
function loadDirectory(cfg) {
  const raw = parseJson(cfg.team_directory, {}) || {};
  const dir = {};
  for (const [k, v] of Object.entries(raw)) dir[lower(k)] = v && typeof v === 'object' ? v : {};
  return dir;
}

// Fills an owner's missing name / email / Slack ID / CRM ID / sequence user ID from the directory.
function resolveOwner(dir, owner, useDefault = true) {
  const o = owner || {};
  let entry = dir[lower(o.email)] || dir[lower(o.crm_id)] || dir[lower(o.name)];
  const hasOwner = clean(o.name) || clean(o.email) || clean(o.crm_id);
  if (!entry && !hasOwner && useDefault) entry = dir.default;
  entry = entry || {};
  return {
    name: clean(o.name) || clean(entry.name),
    email: lower(o.email) || lower(entry.email),
    slack_id: clean(o.slack_id) || clean(entry.slack_id),
    crm_id: clean(o.crm_id) || clean(entry.crm_id),
    sequence_user_id: clean(o.sequence_user_id) || clean(entry.salesloft_user_id || entry.sequence_user_id),
  };
}

// Lookup waterfall: try up to three lookup tools in order, stop as soon as one gives a good answer,
// and never spend more than each tool's monthly budget.
// Pure functions: tested in test/, inlined into the core's lookup Code nodes.


// Slot i (1, 2 or 3) as configured in Config: lookup_<i>_name, lookup_<i>_connector_id, lookup_<i>_monthly_budget.
// A blank budget means no limit. 0 switches the tool off.
function lookupSlot(cfg, i) {
  const id = clean(cfg[`lookup_${i}_connector_id`]);
  if (!id) return null;
  const b = clean(cfg[`lookup_${i}_monthly_budget`]);
  return { index: i, name: lower(cfg[`lookup_${i}_name`]) || `lookup_${i}`, connector_id: id, budget: b === '' ? null : Number(b) };
}

const monthKey = (now) => now.toISOString().slice(0, 7);
const daysAgo = (iso, now) => {
  const d = new Date(clean(iso));
  return isNaN(d.getTime()) ? Infinity : (now - d) / 86400000;
};

function usageFor(usageRows, provider, now) {
  const key = `${monthKey(now)}:${provider}`;
  const row = (usageRows || []).find((u) => clean(u.usage_key) === key);
  return { key, used: row ? Number(row.credits_used) || 0 : 0, warned: row ? lower(row.warned) === 'true' : false };
}

function sameCompany(c, s) {
  const d1 = normDomain(c.last_company_domain);
  const d2 = normDomain(s.job_company_website);
  if (d1 && d2) return d1 === d2;
  return !!lower(s.job_company_name) && lower(s.job_company_name) === lower(c.last_company);
}

// A result answers the question if it shows a current job, and, when we have a "they left" signal,
// it isn't just the old job from data collected before that signal.
function isResolved(c, s) {
  if (!s || !s.found) return false;
  if (!clean(s.job_company_name) && !(Array.isArray(s.experience) && s.experience.length)) return false;
  if (['signal', 'retry', 'recheck'].includes(c.trigger) && sameCompany(c, s)) {
    const verified = new Date(clean(s.job_last_verified) || clean(s.job_last_changed));
    const signal = new Date(clean(c.signal_date));
    if (isNaN(verified.getTime()) || isNaN(signal.getTime()) || verified < signal) return false;
  }
  return true;
}

function cacheIndex(cacheRows) {
  const m = new Map();
  for (const r of cacheRows || []) {
    if (!r || !clean(r.contact_id)) continue;
    m.set(clean(r.contact_id), { ...r, summary: parseJson(r.summary_json, null), tried: parseJson(r.tried_json, {}) || {} });
  }
  return m;
}

function freshCached(cfg, c, row, now) {
  const days = Number(cfg.lookup_cache_days ?? 14);
  if (!row || !row.summary || daysAgo(row.looked_up_at, now) > days) return null;
  return isResolved(c, row.summary) ? row.summary : null;
}

// Who should slot i look up, within its budget?
function planSlot(cfg, i, candidates, cacheRows, usageRows, priorResults, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const slot = lookupSlot(cfg, i);
  const noop = { requests: [{ action: 'noop' }], budget_skipped: [], slot };
  if (!slot || slot.budget === 0) return noop;
  const repeatDays = Number(cfg.lookup_repeat_days ?? 30);
  const cache = cacheIndex(cacheRows);
  const prior = new Map();
  for (const r of priorResults || []) if (r && clean(r.contact_id)) (prior.get(clean(r.contact_id)) || prior.set(clean(r.contact_id), []).get(clean(r.contact_id))).push(r);

  const wanted = [];
  for (const c of candidates || []) {
    const row = cache.get(c.contact_id);
    if (freshCached(cfg, c, row, now)) continue;
    const earlier = prior.get(c.contact_id) || [];
    if (earlier.some((r) => r.pending === true || lower(r.pending) === 'true' || isResolved(c, r))) continue;
    // Applies to manual runs too: the Lookup Callback re-runs people manually, and asking the same tool
    // again right away would loop (and spend a credit each time).
    const triedAt = row && row.tried ? row.tried[slot.name] : '';
    if (daysAgo(triedAt, now) < repeatDays) continue;
    wanted.push({
      action: 'lookup_person',
      contact_id: c.contact_id,
      full_name: c.full_name, first_name: c.first_name, last_name: c.last_name,
      work_email: c.work_email, linkedin_url: c.linkedin_url,
      last_company: c.last_company, last_company_domain: c.last_company_domain, last_title: c.last_title,
    });
  }
  const used = usageFor(usageRows, slot.name, now).used;
  const remaining = slot.budget === null ? Infinity : Math.max(0, slot.budget - used);
  const requests = wanted.slice(0, remaining);
  const skipped = wanted.slice(requests.length).map((r) => r.contact_id);
  return { requests: requests.length ? requests : noop.requests, budget_skipped: skipped, slot };
}

// After all slots ran: pick each person's answer, and work out cache, usage and budget warnings.
function collectLookups(cfg, candidates, cacheRows, usageRows, slotResults, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const nowIso = now.toISOString();
  const warnAt = (Number(cfg.budget_warning_percent ?? 80) || 80) / 100;
  const cache = cacheIndex(cacheRows);
  const slots = [1, 2, 3].map((i) => lookupSlot(cfg, i));

  // Results per person, in slot order, each tagged with its provider.
  const byPerson = new Map();
  const credits = {};
  (slotResults || []).forEach((rows, idx) => {
    const slot = slots[idx];
    for (const r of rows || []) {
      if (!r || !clean(r.contact_id)) continue;
      const provider = lower(r.provider) || (slot && slot.name) || `lookup_${idx + 1}`;
      const res = { ...r, provider };
      (byPerson.get(res.contact_id) || byPerson.set(res.contact_id, []).get(res.contact_id)).push(res);
      credits[provider] = (credits[provider] || 0) + (Number(r.credits_used) || 0);
    }
  });

  const briefs = [];
  const pending = [];
  const cacheOut = [];
  for (const c of candidates || []) {
    const row = cache.get(c.contact_id);
    const results = byPerson.get(c.contact_id) || [];
    const isPending = (r) => r.pending === true || lower(r.pending) === 'true';
    const resolved = results.find((r) => isResolved(c, r));
    const cached = resolved ? null : freshCached(cfg, c, row, now);
    let chosen = resolved || cached;
    const waiting = !chosen && results.some(isPending);

    if (results.length) {
      // A failed call (bad key, outage) doesn't count as "tried", so it is retried next run.
      const tried = { ...(row ? row.tried : {}) };
      for (const r of results) if (!/^Lookup failed/i.test(clean(r.note))) tried[r.provider] = nowIso;
      const keep = resolved || results.find((r) => !isPending(r) && r.found) || results.find((r) => !isPending(r)) || results[0];
      const { contact_id, credits_used, pending: p, action, ...summary } = keep;
      cacheOut.push({
        contact_id: c.contact_id,
        provider: keep.provider,
        found: keep.found ? 'TRUE' : 'FALSE',
        pending: waiting ? 'TRUE' : 'FALSE',
        summary_json: JSON.stringify(summary),
        looked_up_at: nowIso,
        tried_json: JSON.stringify(tried),
        // Remember what started this investigation, so a later re-run (after Clay answers) keeps it.
        signal_json: ['signal', 'retry', 'recheck'].includes(c.trigger)
          ? JSON.stringify({ trigger: c.trigger, signal: c.signal, signal_evidence: c.signal_evidence, signal_date: c.signal_date, saved_at: nowIso })
          : clean(row && row.signal_json),
      });
    }

    // A READY row (async answer that arrived) has now been used: mark it done so it isn't picked up again.
    if (!results.length && row && lower(row.pending) === 'ready') {
      cacheOut.push({ contact_id: c.contact_id, provider: clean(row.provider), found: clean(row.found), pending: 'FALSE', summary_json: clean(row.summary_json), looked_up_at: clean(row.looked_up_at), tried_json: clean(row.tried_json), signal_json: clean(row.signal_json) });
    }
    if (waiting) { pending.push(c.contact_id); continue; }
    if (!chosen) {
      // Nothing resolved it: give the agent the best we have, so it can say [VERIFY] with evidence.
      chosen = results.find((r) => !isPending(r) && r.found)
        || results.find((r) => !isPending(r))
        || (row && row.summary)
        || { found: false, note: 'No lookup tool returned a result (none configured, all over budget, or tried recently).' };
    }
    const { contact_id, credits_used, pending: p, action, email, email_status, ...forAgent } = chosen;
    const emailOk = clean(email) && !/not_unlocked|@domain\.com$/i.test(email) && normDomain(email) === normDomain(chosen.job_company_website);
    briefs.push({
      ...c,
      lookup_source: clean(chosen.provider) || (cached ? clean(row.provider) : ''),
      lookup_email: emailOk ? lower(email) : '',
      lookup_email_status: emailOk ? lower(email_status) : '',
      lookup_json: JSON.stringify(forAgent, null, 1),
    });
  }

  // Usage and budget warnings.
  const usageOut = [];
  const alerts = [];
  for (const [provider, spent] of Object.entries(credits)) {
    if (!spent) continue;
    const slot = slots.find((s) => s && s.name === provider);
    const budget = slot ? slot.budget : null;
    const u = usageFor(usageRows, provider, now);
    const total = u.used + spent;
    let warned = u.warned;
    if (budget && !warned && total >= budget * warnAt) {
      warned = true;
      const pct = Math.round((total / budget) * 100);
      const text = `${provider} has used ${total} of its ${budget} lookup credits this month (${pct}%).${total >= budget ? ' It is now paused until next month; Valari will use the next tool in line.' : ' Valari will pause it at the limit and use the next tool in line.'}`;
      alerts.push({
        action: 'alert', kind: 'budget', contact_id: '',
        subject: `Valari: ${provider} lookup budget at ${pct}%`,
        text_md: `:warning: *Lookup budget:* ${text}`,
        html: `<p><b>Lookup budget:</b> ${text}</p>`,
        text_plain: `Lookup budget: ${text}`,
        to_name: '', to_email: '', to_slack_id: '', cc_name: '', cc_email: '', cc_slack_id: '', priority: '',
      });
    }
    usageOut.push({ usage_key: u.key, month: monthKey(now), provider, credits_used: String(total), budget: budget === null ? '' : String(budget), warned: warned ? 'TRUE' : 'FALSE' });
  }

  return { briefs, pending, cache_rows: cacheOut, usage_rows: usageOut, alerts };
}

// Apollo connector logic: builds the People Enrichment request and trims the response
// to the standard lookup shape. Inlined into the Apollo connector and the n8n template.

// Request body for POST /api/v1/people/match. Phone numbers are never requested (they cost extra credits).
function apolloMatchBody(req) {
  const clean = (v) => String(v ?? '').trim();
  const body = { reveal_personal_emails: false, reveal_phone_number: false };
  if (clean(req.linkedin_url)) body.linkedin_url = clean(req.linkedin_url);
  if (clean(req.work_email)) body.email = clean(req.work_email);
  if (clean(req.first_name)) body.first_name = clean(req.first_name);
  if (clean(req.last_name)) body.last_name = clean(req.last_name);
  if (!clean(req.first_name) && clean(req.full_name)) body.name = clean(req.full_name);
  if (clean(req.last_company)) body.organization_name = clean(req.last_company);
  if (clean(req.last_company_domain)) body.domain = clean(req.last_company_domain);
  return body;
}

function summarizeApollo(res) {
  const clean = (v) => String(v ?? '').trim();
  const r = res || {};
  const p = r.person;
  if (r.error || !p || clean(r.match_confidence).toLowerCase() === 'none') {
    const raw = r.error ? (r.error.message || r.error.description || JSON.stringify(r.error)) : 'No match';
    const noMatch = !r.error || /\b404\b|not found|no match/i.test(String(raw));
    return {
      found: false,
      credits_used: 0,
      note: noMatch && !/credential|unauthor|401|403|key/i.test(String(raw))
        ? 'Apollo has no matching person. This is not evidence that they moved.'
        : `Lookup failed: ${String(raw).slice(0, 200)}`,
    };
  }
  const org = p.organization || {};
  const history = Array.isArray(p.employment_history) ? p.employment_history : [];
  const current = history.find((e) => e && e.current) || {};
  const domain = (s) => clean(s).toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0];
  const experience = history
    .slice()
    .sort((a, b) => String(b.start_date || '').localeCompare(String(a.start_date || '')))
    .slice(0, 6)
    .map((e) => ({
      company: clean(e.organization_name),
      company_website: '',
      title: clean(e.title),
      start_date: clean(e.start_date),
      end_date: e.end_date || null,
      is_primary: Boolean(e.current),
    }));
  return {
    found: true,
    credits_used: 1,
    full_name: clean(p.name),
    linkedin_url: clean(p.linkedin_url),
    location: [p.city, p.state, p.country].map(clean).filter(Boolean).join(', '),
    job_title: clean(p.title) || clean(current.title),
    job_company_name: clean(org.name) || clean(current.organization_name),
    job_company_website: domain(org.primary_domain || org.website_url),
    job_start_date: clean(current.start_date),
    job_last_changed: '',
    job_last_verified: '',
    experience,
    email: clean(p.email),
    email_status: clean(p.email_status),
  };
}

// ---- n8n entry ----
// Who needs an Apollo lookup: skips fresh cached results and people tried recently, and stops at the monthly budget.
const base = $('Config').first().json;
// The template has one lookup tool: Apollo, in slot 1 of the waterfall.
const cfg = { ...base, lookup_1_name: 'apollo', lookup_1_connector_id: 'built-in', lookup_1_monthly_budget: base.apollo_monthly_budget };
const rows = (name) => ($(name).isExecuted ? $(name).all().map((i) => i.json).filter((j) => j && Object.keys(j).length) : []);
const candidates = $('Find Candidates').all().map((i) => i.json);
const { requests, budget_skipped } = planSlot(cfg, 1, candidates, rows('Read Lookup Cache'), rows('Read Usage'), []);
if (budget_skipped.length) console.log('Apollo is at its monthly budget. Skipped:', budget_skipped);
return requests.map((r) => ({ json: r.action === 'noop' ? r : { ...r, apollo_body: apolloMatchBody(r) } }));

// Apollo connector logic: builds the People Enrichment request and trims the response
// to the standard lookup shape. Inlined into the Apollo connector and the n8n template.

// Request body for POST /api/v1/people/match. Phone numbers are never requested (they cost extra credits).
function apolloMatchBody(req) {
  const clean = (v) => String(v ?? '').trim();
  const body = { reveal_personal_emails: false, reveal_phone_number: false };
  if (clean(req.linkedin_url)) body.linkedin_url = clean(req.linkedin_url);
  if (clean(req.work_email)) body.email = clean(req.work_email);
  if (clean(req.first_name)) body.first_name = clean(req.first_name);
  if (clean(req.last_name)) body.last_name = clean(req.last_name);
  if (!clean(req.first_name) && clean(req.full_name)) body.name = clean(req.full_name);
  if (clean(req.last_company)) body.organization_name = clean(req.last_company);
  if (clean(req.last_company_domain)) body.domain = clean(req.last_company_domain);
  return body;
}

function summarizeApollo(res) {
  const clean = (v) => String(v ?? '').trim();
  const r = res || {};
  const p = r.person;
  if (r.error || !p || clean(r.match_confidence).toLowerCase() === 'none') {
    const raw = r.error ? (r.error.message || r.error.description || JSON.stringify(r.error)) : 'No match';
    const noMatch = !r.error || /\b404\b|not found|no match/i.test(String(raw));
    return {
      found: false,
      credits_used: 0,
      note: noMatch && !/credential|unauthor|401|403|key/i.test(String(raw))
        ? 'Apollo has no matching person. This is not evidence that they moved.'
        : `Lookup failed: ${String(raw).slice(0, 200)}`,
    };
  }
  const org = p.organization || {};
  const history = Array.isArray(p.employment_history) ? p.employment_history : [];
  const current = history.find((e) => e && e.current) || {};
  const domain = (s) => clean(s).toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0];
  const experience = history
    .slice()
    .sort((a, b) => String(b.start_date || '').localeCompare(String(a.start_date || '')))
    .slice(0, 6)
    .map((e) => ({
      company: clean(e.organization_name),
      company_website: '',
      title: clean(e.title),
      start_date: clean(e.start_date),
      end_date: e.end_date || null,
      is_primary: Boolean(e.current),
    }));
  return {
    found: true,
    credits_used: 1,
    full_name: clean(p.name),
    linkedin_url: clean(p.linkedin_url),
    location: [p.city, p.state, p.country].map(clean).filter(Boolean).join(', '),
    job_title: clean(p.title) || clean(current.title),
    job_company_name: clean(org.name) || clean(current.organization_name),
    job_company_website: domain(org.primary_domain || org.website_url),
    job_start_date: clean(current.start_date),
    job_last_changed: '',
    job_last_verified: '',
    experience,
    email: clean(p.email),
    email_status: clean(p.email_status),
  };
}

// ---- n8n entry ----
return { json: { contact_id: $('Plan Lookups').item.json.contact_id, provider: 'apollo', ...summarizeApollo($json) } };

// Small helpers shared by the core logic. Inlined into each Code node by scripts/build-workflows.js.

const clean = (v) => String(v ?? '').trim();
const lower = (v) => clean(v).toLowerCase();
const truthy = (v) => ['true', 'yes', '1', 'y'].includes(lower(v));
// Slack markdown: escape its three control characters so names, titles, lookup text or AI output
// can't add links, @channel pings or mentions to an alert.
const mdEsc = (v) => clean(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Only plain http(s) links, with nothing that could break out of a Slack or HTML link (no javascript: or data:).
const safeUrl = (v) => { const u = clean(v); return /^https?:\/\/[^\s<>|"'`]+$/i.test(u) ? u : ''; };

function parseJson(value, fallback) {
  if (value && typeof value === 'object') return value;
  const s = clean(value);
  if (!s) return fallback;
  try { return JSON.parse(s); } catch (e) { return fallback; }
}

function normDomain(s) {
  let d = lower(s);
  if (!d) return '';
  d = d.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0];
  if (d.includes('@')) d = d.split('@').pop();
  return d;
}

function splitName(full) {
  const parts = clean(full).split(/\s+/).filter(Boolean);
  if (!parts.length) return { first_name: '', last_name: '' };
  if (parts.length === 1) return { first_name: parts[0], last_name: '' };
  return { first_name: parts[0], last_name: parts.slice(1).join(' ') };
}

// Stable 1, 2 or 3 from a contact_id, so a third of the list is swept each month without anyone assigning groups.
function sweepGroupFor(id) {
  let h = 0;
  const s = clean(id);
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return String((h % 3) + 1);
}

const isoDay = (d) => d.toISOString().slice(0, 10);

// Team directory (Config): { "<email, CRM owner id or name>": { name, email, slack_id, crm_id, salesloft_user_id }, "default": {...} }
function loadDirectory(cfg) {
  const raw = parseJson(cfg.team_directory, {}) || {};
  const dir = {};
  for (const [k, v] of Object.entries(raw)) dir[lower(k)] = v && typeof v === 'object' ? v : {};
  return dir;
}

// Fills an owner's missing name / email / Slack ID / CRM ID / sequence user ID from the directory.
function resolveOwner(dir, owner, useDefault = true) {
  const o = owner || {};
  let entry = dir[lower(o.email)] || dir[lower(o.crm_id)] || dir[lower(o.name)];
  const hasOwner = clean(o.name) || clean(o.email) || clean(o.crm_id);
  if (!entry && !hasOwner && useDefault) entry = dir.default;
  entry = entry || {};
  return {
    name: clean(o.name) || clean(entry.name),
    email: lower(o.email) || lower(entry.email),
    slack_id: clean(o.slack_id) || clean(entry.slack_id),
    crm_id: clean(o.crm_id) || clean(entry.crm_id),
    sequence_user_id: clean(o.sequence_user_id) || clean(entry.salesloft_user_id || entry.sequence_user_id),
  };
}

// Lookup waterfall: try up to three lookup tools in order, stop as soon as one gives a good answer,
// and never spend more than each tool's monthly budget.
// Pure functions: tested in test/, inlined into the core's lookup Code nodes.


// Slot i (1, 2 or 3) as configured in Config: lookup_<i>_name, lookup_<i>_connector_id, lookup_<i>_monthly_budget.
// A blank budget means no limit. 0 switches the tool off.
function lookupSlot(cfg, i) {
  const id = clean(cfg[`lookup_${i}_connector_id`]);
  if (!id) return null;
  const b = clean(cfg[`lookup_${i}_monthly_budget`]);
  return { index: i, name: lower(cfg[`lookup_${i}_name`]) || `lookup_${i}`, connector_id: id, budget: b === '' ? null : Number(b) };
}

const monthKey = (now) => now.toISOString().slice(0, 7);
const daysAgo = (iso, now) => {
  const d = new Date(clean(iso));
  return isNaN(d.getTime()) ? Infinity : (now - d) / 86400000;
};

function usageFor(usageRows, provider, now) {
  const key = `${monthKey(now)}:${provider}`;
  const row = (usageRows || []).find((u) => clean(u.usage_key) === key);
  return { key, used: row ? Number(row.credits_used) || 0 : 0, warned: row ? lower(row.warned) === 'true' : false };
}

function sameCompany(c, s) {
  const d1 = normDomain(c.last_company_domain);
  const d2 = normDomain(s.job_company_website);
  if (d1 && d2) return d1 === d2;
  return !!lower(s.job_company_name) && lower(s.job_company_name) === lower(c.last_company);
}

// A result answers the question if it shows a current job, and, when we have a "they left" signal,
// it isn't just the old job from data collected before that signal.
function isResolved(c, s) {
  if (!s || !s.found) return false;
  if (!clean(s.job_company_name) && !(Array.isArray(s.experience) && s.experience.length)) return false;
  if (['signal', 'retry', 'recheck'].includes(c.trigger) && sameCompany(c, s)) {
    const verified = new Date(clean(s.job_last_verified) || clean(s.job_last_changed));
    const signal = new Date(clean(c.signal_date));
    if (isNaN(verified.getTime()) || isNaN(signal.getTime()) || verified < signal) return false;
  }
  return true;
}

function cacheIndex(cacheRows) {
  const m = new Map();
  for (const r of cacheRows || []) {
    if (!r || !clean(r.contact_id)) continue;
    m.set(clean(r.contact_id), { ...r, summary: parseJson(r.summary_json, null), tried: parseJson(r.tried_json, {}) || {} });
  }
  return m;
}

function freshCached(cfg, c, row, now) {
  const days = Number(cfg.lookup_cache_days ?? 14);
  if (!row || !row.summary || daysAgo(row.looked_up_at, now) > days) return null;
  return isResolved(c, row.summary) ? row.summary : null;
}

// Who should slot i look up, within its budget?
function planSlot(cfg, i, candidates, cacheRows, usageRows, priorResults, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const slot = lookupSlot(cfg, i);
  const noop = { requests: [{ action: 'noop' }], budget_skipped: [], slot };
  if (!slot || slot.budget === 0) return noop;
  const repeatDays = Number(cfg.lookup_repeat_days ?? 30);
  const cache = cacheIndex(cacheRows);
  const prior = new Map();
  for (const r of priorResults || []) if (r && clean(r.contact_id)) (prior.get(clean(r.contact_id)) || prior.set(clean(r.contact_id), []).get(clean(r.contact_id))).push(r);

  const wanted = [];
  for (const c of candidates || []) {
    const row = cache.get(c.contact_id);
    if (freshCached(cfg, c, row, now)) continue;
    const earlier = prior.get(c.contact_id) || [];
    if (earlier.some((r) => r.pending === true || lower(r.pending) === 'true' || isResolved(c, r))) continue;
    // Applies to manual runs too: the Lookup Callback re-runs people manually, and asking the same tool
    // again right away would loop (and spend a credit each time).
    const triedAt = row && row.tried ? row.tried[slot.name] : '';
    if (daysAgo(triedAt, now) < repeatDays) continue;
    wanted.push({
      action: 'lookup_person',
      contact_id: c.contact_id,
      full_name: c.full_name, first_name: c.first_name, last_name: c.last_name,
      work_email: c.work_email, linkedin_url: c.linkedin_url,
      last_company: c.last_company, last_company_domain: c.last_company_domain, last_title: c.last_title,
    });
  }
  const used = usageFor(usageRows, slot.name, now).used;
  const remaining = slot.budget === null ? Infinity : Math.max(0, slot.budget - used);
  const requests = wanted.slice(0, remaining);
  const skipped = wanted.slice(requests.length).map((r) => r.contact_id);
  return { requests: requests.length ? requests : noop.requests, budget_skipped: skipped, slot };
}

// After all slots ran: pick each person's answer, and work out cache, usage and budget warnings.
function collectLookups(cfg, candidates, cacheRows, usageRows, slotResults, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const nowIso = now.toISOString();
  const warnAt = (Number(cfg.budget_warning_percent ?? 80) || 80) / 100;
  const cache = cacheIndex(cacheRows);
  const slots = [1, 2, 3].map((i) => lookupSlot(cfg, i));

  // Results per person, in slot order, each tagged with its provider.
  const byPerson = new Map();
  const credits = {};
  (slotResults || []).forEach((rows, idx) => {
    const slot = slots[idx];
    for (const r of rows || []) {
      if (!r || !clean(r.contact_id)) continue;
      const provider = lower(r.provider) || (slot && slot.name) || `lookup_${idx + 1}`;
      const res = { ...r, provider };
      (byPerson.get(res.contact_id) || byPerson.set(res.contact_id, []).get(res.contact_id)).push(res);
      credits[provider] = (credits[provider] || 0) + (Number(r.credits_used) || 0);
    }
  });

  const briefs = [];
  const pending = [];
  const cacheOut = [];
  for (const c of candidates || []) {
    const row = cache.get(c.contact_id);
    const results = byPerson.get(c.contact_id) || [];
    const isPending = (r) => r.pending === true || lower(r.pending) === 'true';
    const resolved = results.find((r) => isResolved(c, r));
    const cached = resolved ? null : freshCached(cfg, c, row, now);
    let chosen = resolved || cached;
    const waiting = !chosen && results.some(isPending);

    if (results.length) {
      // A failed call (bad key, outage) doesn't count as "tried", so it is retried next run.
      const tried = { ...(row ? row.tried : {}) };
      for (const r of results) if (!/^Lookup failed/i.test(clean(r.note))) tried[r.provider] = nowIso;
      const keep = resolved || results.find((r) => !isPending(r) && r.found) || results.find((r) => !isPending(r)) || results[0];
      const { contact_id, credits_used, pending: p, action, ...summary } = keep;
      cacheOut.push({
        contact_id: c.contact_id,
        provider: keep.provider,
        found: keep.found ? 'TRUE' : 'FALSE',
        pending: waiting ? 'TRUE' : 'FALSE',
        summary_json: JSON.stringify(summary),
        looked_up_at: nowIso,
        tried_json: JSON.stringify(tried),
        // Remember what started this investigation, so a later re-run (after Clay answers) keeps it.
        signal_json: ['signal', 'retry', 'recheck'].includes(c.trigger)
          ? JSON.stringify({ trigger: c.trigger, signal: c.signal, signal_evidence: c.signal_evidence, signal_date: c.signal_date, saved_at: nowIso })
          : clean(row && row.signal_json),
      });
    }

    // A READY row (async answer that arrived) has now been used: mark it done so it isn't picked up again.
    if (!results.length && row && lower(row.pending) === 'ready') {
      cacheOut.push({ contact_id: c.contact_id, provider: clean(row.provider), found: clean(row.found), pending: 'FALSE', summary_json: clean(row.summary_json), looked_up_at: clean(row.looked_up_at), tried_json: clean(row.tried_json), signal_json: clean(row.signal_json) });
    }
    if (waiting) { pending.push(c.contact_id); continue; }
    if (!chosen) {
      // Nothing resolved it: give the agent the best we have, so it can say [VERIFY] with evidence.
      chosen = results.find((r) => !isPending(r) && r.found)
        || results.find((r) => !isPending(r))
        || (row && row.summary)
        || { found: false, note: 'No lookup tool returned a result (none configured, all over budget, or tried recently).' };
    }
    const { contact_id, credits_used, pending: p, action, email, email_status, ...forAgent } = chosen;
    const emailOk = clean(email) && !/not_unlocked|@domain\.com$/i.test(email) && normDomain(email) === normDomain(chosen.job_company_website);
    briefs.push({
      ...c,
      lookup_source: clean(chosen.provider) || (cached ? clean(row.provider) : ''),
      lookup_email: emailOk ? lower(email) : '',
      lookup_email_status: emailOk ? lower(email_status) : '',
      lookup_json: JSON.stringify(forAgent, null, 1),
    });
  }

  // Usage and budget warnings.
  const usageOut = [];
  const alerts = [];
  for (const [provider, spent] of Object.entries(credits)) {
    if (!spent) continue;
    const slot = slots.find((s) => s && s.name === provider);
    const budget = slot ? slot.budget : null;
    const u = usageFor(usageRows, provider, now);
    const total = u.used + spent;
    let warned = u.warned;
    if (budget && !warned && total >= budget * warnAt) {
      warned = true;
      const pct = Math.round((total / budget) * 100);
      const text = `${provider} has used ${total} of its ${budget} lookup credits this month (${pct}%).${total >= budget ? ' It is now paused until next month; Valari will use the next tool in line.' : ' Valari will pause it at the limit and use the next tool in line.'}`;
      alerts.push({
        action: 'alert', kind: 'budget', contact_id: '',
        subject: `Valari: ${provider} lookup budget at ${pct}%`,
        text_md: `:warning: *Lookup budget:* ${text}`,
        html: `<p><b>Lookup budget:</b> ${text}</p>`,
        text_plain: `Lookup budget: ${text}`,
        to_name: '', to_email: '', to_slack_id: '', cc_name: '', cc_email: '', cc_slack_id: '', priority: '',
      });
    }
    usageOut.push({ usage_key: u.key, month: monthKey(now), provider, credits_used: String(total), budget: budget === null ? '' : String(budget), warned: warned ? 'TRUE' : 'FALSE' });
  }

  return { briefs, pending, cache_rows: cacheOut, usage_rows: usageOut, alerts };
}

// ---- n8n entry ----
// Picks each person's answer and works out the cache, credit usage and the 80% budget warning.
const base = $('Config').first().json;
// The template has one lookup tool: Apollo, in slot 1 of the waterfall.
const cfg = { ...base, lookup_1_name: 'apollo', lookup_1_connector_id: 'built-in', lookup_1_monthly_budget: base.apollo_monthly_budget };
const rows = (name) => ($(name).isExecuted ? $(name).all().map((i) => i.json).filter((j) => j && Object.keys(j).length) : []);
const candidates = $('Find Candidates').all().map((i) => i.json);
return [{ json: collectLookups(cfg, candidates, rows('Read Lookup Cache'), rows('Read Usage'), [rows('Map Apollo'), [], []]) }];

