  let entry = dir[lower(o.email)] || dir[lower(o.crm_id)] || dir[lower(o.name)];
  const hasOwner = clean(o.name) || clean(o.email) || clean(o.crm_id);
  if (!entry && !hasOwner && useDefault) entry = dir.default;
  entry = entry || {};
  return {
    name: clean(o.name) || clean(entry.name),
    email: lower(o.email) || lower(entry.email),
    slack_id: clean(o.slack_id) || clean(entry.slack_id),
    crm_id: clean(o.crm_id) || clean(entry.crm_id),
    sequence_user_id: clean(o.sequence_user_id) || clean(entry.salesloft_user_id || entry.sequence_user_id),
  };
}

// Builds the requests the core sends to optional connectors after a move is confirmed:
// find the new work email, write the move to the CRM, and enroll in a sequence.
// Pure functions: tested in test/, inlined into the matching Code nodes.


const NOOP = [{ action: 'noop' }];

function byContact(rows) {
  const m = new Map();
  for (const r of rows || []) if (r && clean(r.contact_id)) m.set(clean(r.contact_id), r);
  return m;
}

function personName(d) {
  const c = d.candidate;
  const split = splitName(c.full_name);
  return { first_name: clean(c.first_name) || split.first_name, last_name: clean(c.last_name) || split.last_name, full_name: clean(c.full_name) };
}

// Emails the lookup already found at the new company (Apollo returns these), so the email finder can skip them.
function lookupEmailResults(decisions) {
  return (decisions || [])
    .filter((d) => d.outcome === 'confirmed' && clean(d.candidate.lookup_email) && d.new_company_domain && clean(d.candidate.lookup_email).toLowerCase().endsWith(`@${d.new_company_domain}`))
    .map((d) => ({
      contact_id: d.candidate.contact_id,
      email: clean(d.candidate.lookup_email),
      status: lower(d.candidate.lookup_email_status) === 'verified' ? 'valid' : 'unknown',
      confidence: '',
      source: clean(d.candidate.lookup_source) || 'lookup',
    }));
}

function emailRequests(cfg, decisions) {
  const known = new Set(lookupEmailResults(decisions).map((r) => r.contact_id));
  const reqs = decisions
    .filter((d) => d.outcome === 'confirmed' && d.new_company_domain && !known.has(d.candidate.contact_id))
    .map((d) => ({ action: 'find_email', contact_id: d.candidate.contact_id, ...personName(d), domain: d.new_company_domain, company: d.new_company }));
  return reqs.length ? reqs : NOOP;
}

function crmRequests(cfg, decisions, emailResults) {
  if (!truthy(cfg.crm_write_back)) return NOOP;
  const emails = byContact(emailResults);
  const reqs = decisions
    .filter((d) => d.outcome === 'confirmed')
    .map((d) => {
      const c = d.candidate;
      const e = emails.get(c.contact_id) || {};
      const lines = [
        `Former ${c.role_type} at ${c.last_company || 'a previous company'} who used our product. Now ${d.new_title || 'at'} ${d.new_company}.`,
        d.priority ? `Priority: ${d.priority} (${d.score}/100)${d.persona ? `, persona: ${d.persona}` : ''}.` : '',
        d.evidence ? `Evidence:\n${d.evidence}` : '',
        c.notes ? `History with us: ${c.notes}` : '',
        d.draft_opener ? `Draft opener:\n${d.draft_opener}` : '',
      ].filter(Boolean);
      return {
        action: 'record_move',
        contact_id: c.contact_id,
        ...personName(d),
        new_email: clean(e.email),
        new_title: d.new_title,
        new_company: d.new_company,
        new_company_domain: d.new_company_domain,
        crm_account_id: d.crm_account_id,
        owner_crm_id: clean(d.owner.crm_id),
        old_company: c.last_company,
        old_crm_contact_id: c.source === 'product' ? '' : c.contact_id,
        task_subject: `Champion moved: ${c.full_name} is now at ${d.new_company}`,
        task_body: lines.join('\n\n'),
      };
    });
  return reqs.length ? reqs : NOOP;
}

function sequenceRequests(cfg, decisions, emailResults) {
  const minScore = Number(cfg.enroll_min_score ?? 45);
  const emails = byContact(emailResults);
  const reqs = [];
  for (const d of decisions) {
    if (d.outcome !== 'confirmed') continue;
    const e = emails.get(d.candidate.contact_id) || {};
    if (!clean(e.email) || lower(e.status) === 'invalid') continue;
    if ((Number(d.score) || 0) < minScore) continue;
    reqs.push({
      action: 'enroll',
      contact_id: d.candidate.contact_id,
      ...personName(d),
      email: clean(e.email),
      title: d.new_title,
      company: d.new_company,
      company_domain: d.new_company_domain,
      cadence_key: d.bucket,
      persona: d.persona,
      priority: d.priority,
      owner_email: clean(d.owner.email),
      owner_sequence_user_id: clean(d.owner.sequence_user_id),
      note: [d.draft_opener ? `Draft opener:\n${d.draft_opener}` : '', d.evidence ? `Why:\n${d.evidence}` : ''].filter(Boolean).join('\n\n'),
    });
  }
  return reqs.length ? reqs : NOOP;
}

// Combines each decision with what the connectors did (email found, CRM record, sequence)
// and produces the case row, the state row and the alert for each person.
// Pure function: tested in test/, inlined into the "Finalize" Code node.


const esc = (s) => clean(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function finalize(cfg, decisions, emailResults, crmResults, seqResults) {
  const emails = byContact(emailResults);
  const crm = byContact(crmResults);
  const seq = byContact(seqResults);
  const minScore = Number(cfg.enroll_min_score ?? 45);
  const crmName = clean(cfg.crm_name) || 'CRM';
  // Only mention steps that are switched on.
  const emailOn = !!clean(cfg.email_finder_connector_id) || truthy(cfg.find_new_emails) || (emailResults && emailResults.length > 0);
  const seqOn = !!clean(cfg.sequence_connector_id) || (seqResults && seqResults.length > 0);

  return decisions.map((d) => {
    const c = d.candidate;
    const id = c.contact_id;
    const e = emails.get(id) || {};
    const r = crm.get(id) || {};
    const s = seq.get(id) || {};
    const name = c.full_name || c.work_email;
    const tag = (slack, nm) => (/^[A-Z0-9]+$/i.test(clean(slack)) ? `<@${clean(slack)}>` : mdEsc(nm));

    // ---- Status lines for what the connectors did.
    let emailLine = '';
    let crmLine = '';
    let seqLine = '';
    if (d.outcome === 'confirmed') {
      emailLine = clean(e.email)
        ? `${clean(e.email)}${e.status ? ` (${lower(e.status)}${e.confidence !== undefined && e.confidence !== '' ? `, ${e.confidence}%` : ''})` : ''}`
        : (emailOn ? 'Not found' : '');
      if (r.error) crmLine = `Could not write to ${crmName}: ${clean(r.error).slice(0, 160)}`;
      else if (clean(r.crm_record_id)) crmLine = `Created ${lower(r.crm_record_type) || 'record'}${clean(r.task_id) ? ' and a task' : ''}${clean(r.crm_record_url) ? ` (${clean(r.crm_record_url)})` : ''}`;
      else if (!truthy(cfg.crm_write_back)) crmLine = '';
      else crmLine = `Not written to ${crmName}`;
      if (s.enrolled === true || lower(s.enrolled) === 'true') seqLine = `Added to cadence ${clean(s.cadence_name) || clean(s.cadence_id)}. The first email waits for your review.`;
      else if (clean(s.message)) seqLine = `Not enrolled: ${clean(s.message)}`;
      else if (!seqOn) seqLine = '';
      else if (!clean(e.email)) seqLine = 'Not enrolled: no new email';
      else if ((Number(d.score) || 0) < minScore) seqLine = `Not enrolled: score below ${minScore}`;
    }

    // ---- Alert text in three renderings: Slack markdown, HTML (email/Teams), plain text.
    let alert = null;
    if (d.notify) {
      const bucketLabel = { customer: 'Existing customer', open_deal: 'Open deal', lost_deal: 'Lost deal (second chance)', net_new: 'Net new account' }[d.bucket] || '';
      const li = safeUrl(c.linkedin_url);
      const ccNote = d.cc ? ` (cc ${tag(d.cc.slack_id, d.cc.name || d.cc.email)}, who worked with them at ${mdEsc(c.last_company) || 'their last company'})` : '';
      let subject; let md; let html; let plain;
      if (d.outcome === 'confirmed') {
        const fit = [d.persona ? `${d.persona} persona` : '', bucketLabel, `ICP ${d.icp_fit}`, `Confidence ${d.confidence}`, `Was a ${c.role_type}`].filter(Boolean);
        subject = `Champion move: ${name} is now at ${d.new_company} (${d.priority}, ${d.score}/100)`;
        md = [
          `:rotating_light: *Champion move: ${mdEsc(name)}* (${d.priority}, ${d.score}/100)`,
          `${mdEsc(c.last_company) || 'Previous company'} → *${mdEsc(d.new_company)}*${d.new_title ? ` as ${mdEsc(d.new_title)}` : ''}${d.started_new_role ? ` (since ${mdEsc(d.started_new_role)})` : ''}`,
          `${tag(d.owner.slack_id, d.owner.name || d.owner.email) || 'Team'} this one is yours${ccNote}.`,
          `*Fit:* ${fit.join(' · ')}`,
          d.evidence ? `*Why we think so:*\n${mdEsc(d.evidence)}${c.lookup_source ? `\n_Source: ${mdEsc(c.lookup_source)}_` : ''}` : '',
          c.notes ? `*History with us:* ${mdEsc(c.notes)}` : '',
          emailLine ? `*New email:* ${mdEsc(emailLine)}` : '',
          crmLine ? `*${mdEsc(crmName)}:* ${mdEsc(crmLine)}` : '',
          seqLine ? `*Sequence:* ${mdEsc(seqLine)}` : '',
          d.draft_opener ? `*Draft opener (edit before sending):*\n${d.draft_opener.split('\n').map((l) => `> ${mdEsc(l)}`).join('\n')}` : '',
          li ? `<${li}|Open LinkedIn>` : '',
        ].filter(Boolean).join('\n');
        html = [
          `<p><b>Champion move: ${esc(name)}</b> (${esc(d.priority)}, ${esc(d.score)}/100)</p>`,
          `<p>${esc(c.last_company) || 'Previous company'} → <b>${esc(d.new_company)}</b>${d.new_title ? ` as ${esc(d.new_title)}` : ''}${d.started_new_role ? ` (since ${esc(d.started_new_role)})` : ''}</p>`,
          `<p><b>Fit:</b> ${esc(fit.join(' · '))}</p>`,
          d.evidence ? `<p><b>Why we think so:</b><br>${esc(d.evidence).replace(/\n/g, '<br>')}</p>` : '',
          c.notes ? `<p><b>History with us:</b> ${esc(c.notes)}</p>` : '',
          emailLine ? `<p><b>New email:</b> ${esc(emailLine)}</p>` : '',
          crmLine ? `<p><b>${esc(crmName)}:</b> ${esc(crmLine)}</p>` : '',
          seqLine ? `<p><b>Sequence:</b> ${esc(seqLine)}</p>` : '',
          d.draft_opener ? `<p><b>Draft opener (edit before sending):</b></p><blockquote>${esc(d.draft_opener).replace(/\n/g, '<br>')}</blockquote>` : '',
          li ? `<p><a href="${esc(li)}">Open LinkedIn</a></p>` : '',
        ].filter(Boolean).join('\n');
      } else {
        subject = `[VERIFY] ${name} may have left ${c.last_company || 'their company'}`;
        md = [
          `:mag: *[VERIFY] ${mdEsc(name)} may have left ${mdEsc(c.last_company) || 'their company'}*`,
          `${tag(d.owner.slack_id, d.owner.name || d.owner.email) || 'Team'} we have a signal but could not confirm a new role yet. Can you take a quick look? ${li ? `<${li}|Open LinkedIn>` : 'No LinkedIn URL on file'}`,
          d.evidence ? `*What we found:*\n${mdEsc(d.evidence)}` : '',
          `I will recheck automatically on ${mdEsc(d.next_check_on)}.`,
        ].filter(Boolean).join('\n');
        html = [
          `<p><b>[VERIFY] ${esc(name)} may have left ${esc(c.last_company) || 'their company'}</b></p>`,
          `<p>We have a signal but could not confirm a new role yet. Can you take a quick look?${li ? ` <a href="${esc(li)}">Open LinkedIn</a>` : ''}</p>`,
          d.evidence ? `<p><b>What we found:</b><br>${esc(d.evidence).replace(/\n/g, '<br>')}</p>` : '',
          `<p>I will recheck automatically on ${esc(d.next_check_on)}.</p>`,
        ].filter(Boolean).join('\n');
      }
      plain = html.replace(/<br>/g, '\n').replace(/<\/p>/g, '\n').replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&').trim();
      alert = {
        action: 'alert',
        kind: d.outcome === 'confirmed' ? 'move' : 'verify',
        contact_id: id,
        subject, text_md: md, html, text_plain: plain,
        to_name: clean(d.owner.name), to_email: clean(d.owner.email), to_slack_id: clean(d.owner.slack_id),
        cc_name: d.cc ? clean(d.cc.name) : '', cc_email: d.cc ? clean(d.cc.email) : '', cc_slack_id: d.cc ? clean(d.cc.slack_id) : '',
        priority: d.priority,
      };
    }

    const stamp = clean(d.decided_at).replace(/[-:TZ.]/g, '').slice(0, 14);
    const enrolled = s.enrolled === true || lower(s.enrolled) === 'true';
    return {
      case_row: {
        case_id: `${id}-${stamp}`,
        created_at: d.decided_at,
        contact_id: id,
        full_name: c.full_name,
        source: c.source || '',
        trigger: c.trigger,
        signal: c.signal,
        outcome: d.outcome,
        confidence: d.confidence,
        old_company: c.last_company,
        new_company: d.new_company,
        new_company_domain: d.new_company_domain,
        new_title: d.new_title,
        started_new_role: d.started_new_role,
        persona: d.persona,
        icp_fit: d.outcome === 'confirmed' ? d.icp_fit : '',
        bucket: d.bucket,
        score: d.score === '' ? '' : String(d.score),
        priority: d.priority,
        evidence: d.evidence,
        linkedin_url: c.linkedin_url,
        lookup_source: clean(c.lookup_source),
        new_email: clean(e.email),
        crm_record_url: clean(r.crm_record_url) || clean(r.crm_record_id),
        sequence_status: d.outcome === 'confirmed' ? (enrolled ? 'enrolled' : seqLine.replace(/^Not enrolled: /, 'skipped: ')) : '',
        draft_opener: d.draft_opener,
        owner_ae: clean(d.owner.name) || clean(d.owner.email),
        notified: alert ? 'TRUE' : 'FALSE',
        ae_feedback: '',
      },
      state_row: {
        contact_id: id,
        full_name: c.full_name,
        status: d.status,
        last_checked: clean(d.decided_at).slice(0, 10),
        next_check_on: d.next_check_on,
        current_company: d.new_company,
        current_title: d.new_title,
        new_company_domain: d.new_company_domain,
        new_email: clean(e.email),
        moved_at: d.outcome === 'confirmed' ? clean(d.decided_at).slice(0, 10) : '',
        owner_ae: clean(d.owner.name),
        owner_ae_email: clean(d.owner.email),
        owner_ae_slack_id: clean(d.owner.slack_id),
        linkedin_url: c.linkedin_url,
        crm_record_url: clean(r.crm_record_url),
      },
      alert,
    };
  });
}

// ---- n8n entry ----
const decisions = $('Score and Route').all().map((i) => i.json);
const found = $('Map Emails').isExecuted ? $('Map Emails').all().map((i) => i.json).filter((j) => j && j.contact_id) : [];
const emails = [...lookupEmailResults(decisions), ...found];
return finalize($('Config').first().json, decisions, emails, [], []).map((json) => ({ json }));

// Small helpers shared by the core logic. Inlined into each Code node by scripts/build-workflows.js.

const clean = (v) => String(v ?? '').trim();
const lower = (v) => clean(v).toLowerCase();
const truthy = (v) => ['true', 'yes', '1', 'y'].includes(lower(v));
// Slack markdown: escape its three control characters so names, titles, lookup text or AI output
// can't add links, @channel pings or mentions to an alert.
const mdEsc = (v) => clean(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Only plain http(s) links, with nothing that could break out of a Slack or HTML link (no javascript: or data:).
const safeUrl = (v) => { const u = clean(v); return /^https?:\/\/[^\s<>|"'`]+$/i.test(u) ? u : ''; };

function parseJson(value, fallback) {
  if (value && typeof value === 'object') return value;
  const s = clean(value);
  if (!s) return fallback;
  try { return JSON.parse(s); } catch (e) { return fallback; }
}

function normDomain(s) {
  let d = lower(s);
  if (!d) return '';
  d = d.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0];
  if (d.includes('@')) d = d.split('@').pop();
  return d;
}

function splitName(full) {
  const parts = clean(full).split(/\s+/).filter(Boolean);
  if (!parts.length) return { first_name: '', last_name: '' };
  if (parts.length === 1) return { first_name: parts[0], last_name: '' };
  return { first_name: parts[0], last_name: parts.slice(1).join(' ') };
}

// Stable 1, 2 or 3 from a contact_id, so a third of the list is swept each month without anyone assigning groups.
function sweepGroupFor(id) {
  let h = 0;
  const s = clean(id);
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return String((h % 3) + 1);
}

const isoDay = (d) => d.toISOString().slice(0, 10);

// Team directory (Config): { "<email, CRM owner id or name>": { name, email, slack_id, crm_id, salesloft_user_id }, "default": {...} }
function loadDirectory(cfg) {
  const raw = parseJson(cfg.team_directory, {}) || {};
  const dir = {};
  for (const [k, v] of Object.entries(raw)) dir[lower(k)] = v && typeof v === 'object' ? v : {};
  return dir;
}

// Fills an owner's missing name / email / Slack ID / CRM ID / sequence user ID from the directory.
function resolveOwner(dir, owner, useDefault = true) {
  const o = owner || {};
  let entry = dir[lower(o.email)] || dir[lower(o.crm_id)] || dir[lower(o.name)];
  const hasOwner = clean(o.name) || clean(o.email) || clean(o.crm_id);
  if (!entry && !hasOwner && useDefault) entry = dir.default;
  entry = entry || {};
  return {
    name: clean(o.name) || clean(entry.name),
    email: lower(o.email) || lower(entry.email),
    slack_id: clean(o.slack_id) || clean(entry.slack_id),
    crm_id: clean(o.crm_id) || clean(entry.crm_id),
    sequence_user_id: clean(o.sequence_user_id) || clean(entry.salesloft_user_id || entry.sequence_user_id),
  };
}

// Builds the digest (email HTML plus Slack markdown) from the cases table.
// Pure function: tested in test/, inlined into the "Build Digest" Code node.


function buildDigest(cfg, cases, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const days = Number(cfg.digest_lookback_days) || 14;
  const since = new Date(now.getTime() - days * 86400000);
  const esc = (s) => clean(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const fmt = (d) => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });

  const recent = (cases || []).filter((c) => {
    const d = new Date(clean(c.created_at));
    return clean(c.case_id) && !isNaN(d.getTime()) && d >= since && d <= now;
  });
  const latest = new Map();
  for (const c of recent) {
    const prev = latest.get(c.contact_id);
    if (!prev || new Date(c.created_at) > new Date(prev.created_at)) latest.set(c.contact_id, c);
  }
  const rows = [...latest.values()];
  const confirmed = rows.filter((c) => c.outcome === 'confirmed').sort((a, b) => (Number(b.score) || 0) - (Number(a.score) || 0));
  const verify = rows.filter((c) => c.outcome === 'verify');
  const enrolled = confirmed.filter((c) => lower(c.sequence_status) === 'enrolled').length;
  const meetings = rows.filter((c) => ['meeting_booked', 'opportunity'].includes(lower(c.ae_feedback))).length;

  const bucketLabel = { customer: 'Existing customer', open_deal: 'Open deal', lost_deal: 'Lost deal', net_new: 'Net new' };
  const th = 'style="text-align:left;padding:8px;border-bottom:2px solid #1f2937;font-size:13px"';
  const td = 'style="padding:8px;border-bottom:1px solid #e5e7eb;font-size:13px;vertical-align:top"';
  const link = (url, label) => (safeUrl(url) ? `<a href="${esc(safeUrl(url))}">${esc(label)}</a>` : '');
  const title = clean(cfg.digest_title) || 'Champion moves';
  const range = `${fmt(since)} to ${fmt(now)}`;
  const subject = `${title}: ${confirmed.length} confirmed, ${verify.length} to verify (${range})`;
  const funnel = `${rows.length} investigated · ${confirmed.length} confirmed · ${enrolled} enrolled in a sequence · ${meetings} meetings or opportunities logged`;

  const html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#111827;max-width:780px">
<h2 style="margin:0 0 4px">${esc(title)}</h2>
<p style="margin:0 0 16px;color:#6b7280;font-size:13px">${range} · ${esc(funnel)}</p>
<h3 style="margin:16px 0 8px">Confirmed moves (${confirmed.length})</h3>
${confirmed.length ? `<table style="border-collapse:collapse;width:100%">
<tr><th ${th}>Person</th><th ${th}>Move</th><th ${th}>New title</th><th ${th}>Persona</th><th ${th}>Account</th><th ${th}>Priority</th><th ${th}>Sequence</th><th ${th}>Owner</th></tr>
${confirmed.map((c) => `<tr><td ${td}>${esc(c.full_name)}<br>${link(c.linkedin_url, 'LinkedIn')}</td><td ${td}>${esc(c.old_company)} → <b>${esc(c.new_company)}</b></td><td ${td}>${esc(c.new_title)}</td><td ${td}>${esc(c.persona)}</td><td ${td}>${esc(bucketLabel[c.bucket] || c.bucket)}</td><td ${td}>${esc(c.priority)} (${esc(c.score)})</td><td ${td}>${esc(c.sequence_status)}</td><td ${td}>${esc(c.owner_ae)}</td></tr>`).join('\n')}
</table>` : '<p style="font-size:13px;color:#6b7280">No confirmed moves in this period.</p>'}
<h3 style="margin:24px 0 8px">Needs a manual check [VERIFY] (${verify.length})</h3>
${verify.length ? `<ul style="font-size:13px;padding-left:18px">${verify.map((c) => `<li><b>${esc(c.full_name)}</b> (${esc(c.old_company)}), owner ${esc(c.owner_ae) || 'unassigned'}. ${link(c.linkedin_url, 'Check LinkedIn')}</li>`).join('')}</ul>` : '<p style="font-size:13px;color:#6b7280">Nothing waiting on a manual check.</p>'}
<p style="margin-top:24px;font-size:12px;color:#6b7280">Full history is in the valari_cases data table. Set ae_feedback there (useful, not_useful, wrong_person, contacted, meeting_booked, opportunity) so scoring can be tuned.</p>
</div>`;

  const md = [
    `*${mdEsc(title)}* (${range})`,
    funnel,
    '',
    `*Confirmed moves (${confirmed.length})*`,
    ...(confirmed.length ? confirmed.map((c) => `• ${mdEsc(c.priority)} ${mdEsc(c.score)}: *${mdEsc(c.full_name)}* ${mdEsc(c.old_company)} → *${mdEsc(c.new_company)}*${c.new_title ? `, ${mdEsc(c.new_title)}` : ''}${c.persona ? ` (${mdEsc(c.persona)})` : ''} · ${mdEsc(c.owner_ae) || 'unassigned'}`) : ['No confirmed moves.']),
    '',
    `*Needs a manual check [VERIFY] (${verify.length})*`,
    ...(verify.length ? verify.map((c) => `• ${mdEsc(c.full_name)} (${mdEsc(c.old_company)}) · ${mdEsc(c.owner_ae) || 'unassigned'}${safeUrl(c.linkedin_url) ? ` · <${safeUrl(c.linkedin_url)}|LinkedIn>` : ''}`) : ['Nothing waiting.']),
  ].join('\n');

  return { action: 'digest', subject, html, text_md: md, confirmed: confirmed.length, verify: verify.length, checked: rows.length, enrolled, meetings };
}

